import{_ as s,o as a,c as n,a2 as e}from"./chunks/framework.B4hAkGey.js";const k=JSON.parse('{"title":"4.1 基础入门：NAT 与穿透难题","description":"","frontmatter":{},"headers":[],"relativePath":"guide/04-ice-stun-turn/basics.md","filePath":"guide/04-ice-stun-turn/basics.md","lastUpdated":1792683941000}'),i={name:"guide/04-ice-stun-turn/basics.md"};function d(p,t,l,r,h,o){return a(),n("div",null,[...t[0]||(t[0]=[e(`<h1 id="_4-1-基础入门-nat-与穿透难题" tabindex="-1">4.1 基础入门：NAT 与穿透难题 <a class="header-anchor" href="#_4-1-基础入门-nat-与穿透难题" aria-label="Permalink to &quot;4.1 基础入门：NAT 与穿透难题&quot;">​</a></h1><blockquote><p>两台各在 NAT 后面的电脑，怎么直接找到对方并建立 P2P 连接？这就是 ICE/STUN/TURN 要解决的核心问题。</p></blockquote><hr><h2 id="_4-1-1-什么是-nat" tabindex="-1">4.1.1 什么是 NAT <a class="header-anchor" href="#_4-1-1-什么是-nat" aria-label="Permalink to &quot;4.1.1 什么是 NAT&quot;">​</a></h2><p><strong>NAT = Network Address Translation（网络地址转换）</strong>，路由器把内网的私有 IP 地址映射成公网 IP 地址。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>公网（唯一）        内网（私有，可重复）</span></span>
<span class="line"><span>                    ├── 192.168.1.1  (路由器自己)</span></span>
<span class="line"><span>  114.242.34.5  ◄── ├── 192.168.1.2  (标签君的电脑)</span></span>
<span class="line"><span>                    ├── 192.168.1.3  (标签君的手机)</span></span>
<span class="line"><span>                    └── 192.168.1.4  (另一台)</span></span></code></pre></div><p><strong>问题来了</strong>：标签君在 192.168.1.2，你在另一个 NAT 后的 10.0.0.5——你们的 IP 地址互相看不到、也不能直接发数据包。</p><hr><h2 id="_4-1-2-传统解决方案" tabindex="-1">4.1.2 传统解决方案 <a class="header-anchor" href="#_4-1-2-传统解决方案" aria-label="Permalink to &quot;4.1.2 传统解决方案&quot;">​</a></h2><table tabindex="0"><thead><tr><th>方案</th><th>延迟</th><th>带宽成本</th><th>说明</th></tr></thead><tbody><tr><td><strong>客户端-服务器（C/S）</strong></td><td>低</td><td>高</td><td>所有流量经服务器转发，服务器压力大</td></tr><tr><td><strong>STUN</strong></td><td>低</td><td>极低</td><td>告诉客户端&quot;你公网 IP 是什么&quot;，但<strong>不是所有 NAT 类型都能穿透</strong></td></tr><tr><td><strong>TURN</strong></td><td>略高</td><td>高</td><td>STUN 失败时的<strong>中继服务器</strong>兜底，所有流量经 TURN</td></tr><tr><td><strong>ICE</strong></td><td>动态</td><td>动态</td><td><strong>STUN + TURN + 直连</strong>综合，自动选择最优路径</td></tr></tbody></table><p>WebRTC 用的就是 <strong>ICE 框架</strong>——自动尝试直连 → STUN 反射 → TURN 中继，选第一个能通的。</p><hr><h2 id="_4-1-3-nat-类型与穿透能力" tabindex="-1">4.1.3 NAT 类型与穿透能力 <a class="header-anchor" href="#_4-1-3-nat-类型与穿透能力" aria-label="Permalink to &quot;4.1.3 NAT 类型与穿透能力&quot;">​</a></h2><p>NAT 分为 4 种类型，穿透难度递增：</p><table tabindex="0"><thead><tr><th>NAT 类型</th><th>英文名</th><th>穿透难度</th><th>STUN 能否穿透</th><th>TURN</th></tr></thead><tbody><tr><td>1 · 完全锥形</td><td>Full Cone</td><td>⭐</td><td>✅ 100% 成功</td><td>兜底</td></tr><tr><td>2 · 受限锥形</td><td>Restricted Cone</td><td>⭐⭐</td><td>✅ 通常能成功</td><td>兜底</td></tr><tr><td>3 · 端口受限锥形</td><td>Port-Restricted Cone</td><td>⭐⭐⭐</td><td>⚠️ 有时能成功</td><td>兜底</td></tr><tr><td>4 · 对称 NAT</td><td>Symmetric NAT</td><td>⭐⭐⭐⭐</td><td>❌ 基本失败</td><td>✅ 必须用</td></tr></tbody></table><p><strong>大多数公司 / 运营商 / 5G 核心网</strong>的 NAT 是类型 4（对称 NAT）——<strong>必须走 TURN</strong>。这也是 TURN 服务器不可替代的原因。</p><hr><h2 id="_4-1-4-ice-候选收集流程" tabindex="-1">4.1.4 ICE 候选收集流程 <a class="header-anchor" href="#_4-1-4-ice-候选收集流程" aria-label="Permalink to &quot;4.1.4 ICE 候选收集流程&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>┌─────────────────────────────────────────────────────────────┐</span></span>
<span class="line"><span>│  ICE Agent（WebRTC 内部）                                    │</span></span>
<span class="line"><span>│                                                              │</span></span>
<span class="line"><span>│  1. 收集候选地址                                              │</span></span>
<span class="line"><span>│     ├── Host 候选（本机 IP）                                │</span></span>
<span class="line"><span>│     ├── Server-Reflexive 候选（STUN 反射地址）              │</span></span>
<span class="line"><span>│     └── Relayed 候选（TURN 中继地址）                       │</span></span>
<span class="line"><span>│                                                              │</span></span>
<span class="line"><span>│  2. 候选交换（通过信令通道）                                  │</span></span>
<span class="line"><span>│                                                              │</span></span>
<span class="line"><span>│  3. 连通性检查（用 STUN 绑定请求探测）                        │</span></span>
<span class="line"><span>│     └── 同时测试多个候选对，找到第一个能通的                  │</span></span>
<span class="line"><span>│                                                              │</span></span>
<span class="line"><span>│  4. 选定候选对 → 媒体开始传输                                 │</span></span>
<span class="line"><span>└─────────────────────────────────────────────────────────────┘</span></span></code></pre></div><p><strong>候选类型优先级</strong>（从高到低）：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Host（同局域网直连）</span></span>
<span class="line"><span>  ↓</span></span>
<span class="line"><span>Server-Reflexive（STUN 反射，NAT 类型 1-3）</span></span>
<span class="line"><span>  ↓</span></span>
<span class="line"><span>Relayed（TURN 中继，NAT 类型 4 兜底）</span></span></code></pre></div><blockquote><p><strong>注意</strong>：同局域网的两台设备，Host 候选通常直接命中——不需要 STUN/TURN，延迟最低。</p></blockquote><hr><h2 id="_4-1-5-ice-状态机" tabindex="-1">4.1.5 ICE 状态机 <a class="header-anchor" href="#_4-1-5-ice-状态机" aria-label="Permalink to &quot;4.1.5 ICE 状态机&quot;">​</a></h2><p><code>RTCPeerConnection.iceConnectionState</code>：</p><table tabindex="0"><thead><tr><th>状态</th><th>含义</th></tr></thead><tbody><tr><td><code>new</code></td><td>初始，未收集</td></tr><tr><td><code>checking</code></td><td>正在收集候选并探测连通性</td></tr><tr><td><code>connected</code></td><td>已找到可用候选对 ✅</td></tr><tr><td><code>completed</code></td><td>候选都收集完、连通性检查也都做完</td></tr><tr><td><code>failed</code></td><td>所有候选对都不通 ❌</td></tr><tr><td><code>disconnected</code></td><td>连接暂时断了（网络波动）</td></tr><tr><td><code>closed</code></td><td>PeerConnection 已关闭</td></tr></tbody></table><p>监听状态变化：</p><div class="language-js vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">js</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">pc.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">addEventListener</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;iceconnectionstatechange&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, () </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> {</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  console.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">log</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;ICE 状态:&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, pc.iceConnectionState)</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  </span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">  if</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> (pc.iceConnectionState </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">===</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;failed&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">) {</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">    // 穿透失败，引导用户检查网络 / 切换 TURN 服务器</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  }</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">  if</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> (pc.iceConnectionState </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">===</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;disconnected&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">) {</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">    // 短暂断连，WebRTC 会自动重连</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  }</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">})</span></span></code></pre></div><hr><h2 id="_4-1-6-小结" tabindex="-1">4.1.6 小结 <a class="header-anchor" href="#_4-1-6-小结" aria-label="Permalink to &quot;4.1.6 小结&quot;">​</a></h2><table tabindex="0"><thead><tr><th>你应该记住</th><th></th></tr></thead><tbody><tr><td><strong>NAT 是穿透难题的根源</strong></td><td>内网 IP 互相不可见</td></tr><tr><td><strong>ICE = STUN + TURN + 直连</strong></td><td>自动选最优路径</td></tr><tr><td><strong>Host &gt; Server-Reflexive &gt; Relayed</strong></td><td>候选优先级</td></tr><tr><td><strong>对称 NAT（类型 4）必须 TURN</strong></td><td>运营商/企业网常见</td></tr><tr><td><strong>同局域网直连</strong></td><td>Host 候选直接命中</td></tr></tbody></table><hr><h2 id="下一节" tabindex="-1">下一节 <a class="header-anchor" href="#下一节" aria-label="Permalink to &quot;下一节&quot;">​</a></h2><p>→ <a href="./advanced">4.2 进阶应用：ICE 候选收集与连通性检查</a></p>`,34)])])}const g=s(i,[["render",d]]);export{k as __pageData,g as default};
